// Module paths
project(":shared").projectDir = file("src/shared")
project(":cli").projectDir = file("src/cli")
project(":backendng").projectDir = file("src/backendng")
# KSP2 (Micronaut annotation processing) runs INSIDE the Gradle daemon
# (KspAATask uses a noIsolation worker — there is no separate KSP process or
# per-task heap setting), and its measured live-set for :backendng is ~4.9 GiB.
# The daemon heap must therefore be >= ~5 GiB; 5632m leaves headroom for growth.
org.gradle.jvmargs=-Xmx5632m -XX:MaxMetaspaceSize=1g -XX:+UseG1GC -XX:G1HeapRegionSize=8m -XX:+UseStringDeduplication -Dfile.encoding=UTF-8 -XX:+HeapDumpOnOutOfMemoryError
# Run the Kotlin compiler in the Gradle daemon instead of a second 3 GiB
# daemon JVM: the reference build host (AWS m5.large) has 8 GiB total, which
# cannot hold a 5.5 GiB KSP daemon and a separate Kotlin daemon at the same
# time. KSP and kotlinc peak sequentially, so one JVM sized for KSP covers both.
kotlin.compiler.execution.strategy=in-process
# Only used if the in-process strategy above is ever reverted.
kotlin.daemon.jvmargs=-Xmx3g -XX:MaxMetaspaceSize=512m -XX:+HeapDumpOnOutOfMemoryError
# KSP incremental processing is OFF deliberately, and :backendng does not build
# without it. Micronaut's ConfigurationMetadataWriterVisitor keeps KSP symbols and
# reads them again in finish(), after the Analysis API session that created them has
# closed. With incremental on, every real kspKotlin execution dies with:
#   e: [ksp] Error finalizing type visitor [io.micronaut.context.visitor.
#   ConfigurationMetadataWriterVisitor]: ... PSI has changed since creation
# Confirmed on Kotlin 2.4.20 / KSP 2.3.12 against micronaut-inject-kotlin 5.1.4;
# it is not a Micronaut patch-level bug, so a patch bump alone does not help.
# KSP1 is no longer a fallback. Note this was invisible for
# days: org.gradle.caching=true served kspKotlin FROM-CACHE, so the processor never
# actually ran until an input changed. Re-test before ever turning this back on.
ksp.incremental=false
org.gradle.workers.max=2
org.gradle.parallel=true
org.gradle.configuration-cache=true
org.gradle.caching=true
