import { defineConfig } from "astro/config";
import react from "@astrojs/react";
import node from "@astrojs/node";


const allowedDomain = process.env.SECMAN_DOMAIN || "http://localhost:4321";
const allowedHost = process.env.SECMAN_HOST || "localhost";
const backendProxy = {
  target: allowedDomain,
  changeOrigin: true,
  secure: false,
  ...(process.env.SECMAN_E2E_FRONTEND_DIR && {
    configure(proxy) {
      // The disposable stack uses separate ports; production uses this shared origin.
      proxy.on('proxyReq', (request) => request.setHeader('Origin', 'https://secman.covestro.net'));
    },
  }),
};

// Suppress noisy Vite warnings that are not actionable:
// - "externalized for browser compatibility" from @astrojs/node server-side dependencies
// - "emitFile() is not supported in serve mode" from astro:scripts plugin (known Astro issue)
const suppressDevWarnings = {
  name: "suppress-dev-warnings",
  configResolved(config) {
    const originalWarn = config.logger.warn;
    config.logger.warn = (msg, options) => {
      if (typeof msg === "string" && (
        msg.includes("externalized for browser compatibility") ||
        msg.includes("emitFile() is not supported in serve mode")
      )) return;
      originalWarn(msg, options);
    };
  },
};


// https://astro.build/config
export default defineConfig({
  integrations: [react()],
  output: "server",
  adapter: node({
    mode: "standalone",
  }),
  server: {
    host: process.env.SECMAN_E2E_FRONTEND_HOST ? "127.0.0.1" : true,
    port: Number(process.env.SECMAN_FRONTEND_PORT || 4321),
  },
  vite: {
    plugins: [suppressDevWarnings],
    optimizeDeps: {
      // exceljs is reached only through `await import('exceljs')` inside React
      // islands, which the dev-time dep scan (entered from .astro pages) never
      // walks into. The resolver still rewrites the specifier to
      // node_modules/.vite/deps/exceljs.js, so without this the file is never
      // prebundled and every Excel export dies with "Importing a module script
      // failed". Production builds are unaffected — Rollup follows dynamic
      // imports.
      include: ["exceljs"],
    },
    build: {
      // exceljs minified is ~916 KB intrinsically; raise the threshold so the
      // warning fires only on chunks that are actually fixable.
      chunkSizeWarningLimit: 1000,
    },
    server: {
      fs: process.env.SECMAN_E2E_ORIGINAL_FRONTEND_DIR
        ? { allow: [process.cwd(), process.env.SECMAN_E2E_ORIGINAL_FRONTEND_DIR] }
        : undefined,
        allowedHosts: [
            allowedHost,
            "secman.schmall.io"
        ],
      proxy: {
        "/api": backendProxy,
        "/oauth": backendProxy,
        "/mcp": backendProxy,
      },
    },
  },
});

