     * List all workgroups
     * FR-005: ADMIN only, returns all workgroups with counts
     *
     * GET /api/workgroups
     * Returns: 200 OK with array of workgroups
     */
    @Get
    @Secured(SecurityRule.IS_AUTHENTICATED)
    @Transactional
    open fun listWorkgroups(authentication: Authentication): HttpResponse<List<WorkgroupListResponse>> {
        // ADMIN and SECCHAMPION see every workgroup; regular users see only the
        // workgroups they are members of (privacy default — see /workgroups UX).
        val workgroups = if (com.secman.security.GrantAuthority.canManage(authentication.roles)) {
            workgroupService.listAllWorkgroups()
        } else {
            val user = currentUser(authentication)
            // Only enabled, directly joined workgroups grant membership visibility.
            workgroupRepository.findWorkgroupsByUserEmail(user.email)
        }

        // Performance: build all per-workgroup data with a constant number of
        // bulk queries instead of the previous N+1 explosion (N×(4+2·depth)+1
        // queries for 1000+ workgroups). Each lookup below is one query whose
        // cost is independent of the workgroup count.
        val userCounts = workgroupRepository.countUsersPerWorkgroup().toCountMap()
        val assetCounts = workgroupRepository.countAssetsPerWorkgroup().toCountMap()
        val awsCounts = workgroupAwsAccountRepository.countPerWorkgroup().toCountMap()
        val adCounts = workgroupAdDomainRepository.countPerWorkgroup().toCountMap()
        // id -> (parentId, name) for ALL workgroups; powers in-memory ancestor /
        // depth computation without touching the lazy `parent` association.
        val links: Map<Long, Pair<Long?, String>> = workgroupRepository.findAllParentLinks()
            .associate { row ->
                (row[0] as Number).toLong() to Pair((row[1] as Number?)?.toLong(), row[2] as String)
            }

        val visibleIds = workgroups.mapNotNull { it.id }.toSet()
        val visibleLinks = if (canManageWorkgroup(authentication)) links else links.filterKeys { it in visibleIds }
        val response = workgroups.map { wg ->
            val id = wg.id!!
            WorkgroupListResponse(
                id = id,
                name = wg.name,
                description = wg.description,
                ownerEmail = wg.ownerEmail,
                awsAccountManaged = wg.awsAccountManaged,
                criticality = wg.criticality,
                enabled = wg.enabled,
                userCount = (userCounts[id] ?: 0L).toInt(),
                assetCount = (assetCounts[id] ?: 0L).toInt(),
                awsAccountsCount = awsCounts[id] ?: 0L,
                adDomainsCount = adCounts[id] ?: 0L,
                createdAt = wg.createdAt!!,
                updatedAt = wg.updatedAt!!,
                parentId = wg.parent?.id?.takeIf { it in visibleLinks },
                parentName = wg.parent?.id?.let { visibleLinks[it]?.second },
                depth = depthFromLinks(id, visibleLinks),
                ancestors = ancestorsFromLinks(id, visibleLinks)
            )
        }
        return HttpResponse.ok(response)
    }

    /** Convert a (workgroupId, count) projection into a id->count map. */
    private fun List<Array<Any>>.toCountMap(): Map<Long, Long> =
        associate { row -> (row[0] as Number).toLong() to (row[1] as Number).toLong() }
  return (
    <div className="container-fluid mt-4 d-flex flex-column flex-grow-1" style={{ minHeight: 0 }}>
      <div className="d-flex justify-content-between align-items-center mb-4 flex-shrink-0">
        <h2>Workgroup Management</h2>
        <button disabled={!canChangeStatus} className="btn btn-primary" onClick={() => setShowForm(true)}>
          Create Workgroup
        </button>
      </div>

      {error && (
        <div className="alert alert-danger alert-dismissible fade show" role="alert">
          {error}
          <button type="button" className="btn-close" onClick={() => setError(null)}></button>
        </div>
      )}

      {/* Create/Edit Form Modal */}
      {showForm && (
        <WorkgroupFormModal
          workgroup={editingWorkgroup}
          onClose={closeForm}
          onSaved={async () => {
            await fetchWorkgroups();
            closeForm();
            setError(null);
          }}
          onError={setError}
