import { execFileSync } from 'node:child_process';
const require = createRequire('/Users/flake/sources/misc/secman/tests/e2e/package.json');
const { chromium } = require('playwright');
let host = process.env.SECMAN_HOST.replace(/\/$/, '');
if (!host.includes('://')) host = `https://${host}`;
const dir = mkdtempSync(join(tmpdir(), 'secman-workgroup-read-'));
const jar = join(dir, 'cookies');
let browser;
try {
  const login = JSON.parse(execFileSync('/usr/bin/curl', ['-sS', '--fail-with-body', '-c', jar,
    '-H', 'Content-Type: application/json', '--data-binary', '@-', `${host}/api/auth/login`], {
    input: JSON.stringify({ username: process.env.SECMAN_ADMIN_NAME, password: process.env.SECMAN_ADMIN_PASS }),
    encoding: 'utf8',
  }));
  const workgroups = JSON.parse(execFileSync('/usr/bin/curl', ['-sS', '--fail-with-body', '-b', jar,
    `${host}/api/workgroups`], { encoding: 'utf8' }));
  const cookies = readFileSync(jar, 'utf8').split('\n').filter(line => line && (!line.startsWith('#') || line.startsWith('#HttpOnly_'))).map(line => {
    const parts = line.replace(/^#HttpOnly_/, '').split('\t');
    return { name: parts[5], value: parts[6], domain: parts[0], path: parts[2], secure: parts[3] === 'TRUE',
      httpOnly: line.startsWith('#HttpOnly_'), expires: Number(parts[4]) || -1, sameSite: 'Lax' };
  });
  browser = await chromium.launch();
  const context = await browser.newContext({ storageState: { cookies, origins: [] } });
  const user = Object.fromEntries(['id', 'username', 'email', 'roles', 'workgroupCount', 'awsAccountCount', 'domainCount'].map(key => [key, login[key]]));
  await context.addInitScript(user => sessionStorage.setItem('user', JSON.stringify(user)), user);
  const page = await context.newPage();
  await page.goto(`${host}/workgroups`);
  await page.getByRole('button', { name: 'Table View' }).click();
  const aws = workgroups.filter(wg => wg.name.trim().toUpperCase().startsWith('AWS-'));
  const filteredCount = workgroups.length - aws.length;
  await page.waitForFunction(expected => document.querySelectorAll('table tbody tr').length === expected, filteredCount);
  const off = await page.locator('table tbody tr').count();
  const firstNames = await page.locator('table tbody tr td:nth-child(2)').allTextContents();
  await page.locator('#showAwsWorkgroups').check();
  await page.waitForFunction(expected => document.querySelectorAll('table tbody tr').length === expected, workgroups.length);
  const on = await page.locator('table tbody tr').count();
  const shownNames = new Set((await page.locator('table tbody tr td:nth-child(2)').allTextContents()).map(name => name.trim()));
  console.log(JSON.stringify({ apiCount: workgroups.length, renderedRowsToggleOff: off, renderedRowsToggleOn: on,
    missingNames: workgroups.filter(wg => !shownNames.has(wg.name.trim())).map(wg => wg.name), firstVisibleNames: firstNames.slice(0, 6).map(name => name.trim()) }, null, 2));
} finally { if (browser) await browser.close(); rmSync(dir, { recursive: true, force: true }); }
